-- Aula 05 · Data Collection and Storage · 07/11/2026, 8h30 · quiz de abertura sobre o servidor de ingestão da Aula 04.
-- Substitui o TBL da Aula 04 que abria a aula. As perguntas usam as medições do material da Aula 04.
-- Usa as tabelas/RPCs já instaladas no Postgres da VPS (ver supabase/README.md). Não execute o schema destrutivo.
-- Reexecução preserva IDs; recusa alterar sala iniciada ou com participantes.
-- O token do professor entra pelo marcador __QUIZ_HOST_TOKEN__, trocado pelo valor do .env na aplicação
-- (npm run quiz:dc-aula05:apply, que chama scripts/quiz_db.mjs com --token-env DCS_HOST_TOKEN).
begin;
select pg_advisory_xact_lock(hashtext('mack-dcs-a05-2026-2'));
do $$ begin if exists (select 1 from quiz_sessions where slug='mack-dcs-a05-2026-2' and (estado <> 'lobby' or pergunta_atual <> 0)) or exists (select 1 from quiz_players where session_slug='mack-dcs-a05-2026-2') then raise exception 'Sala já iniciada ou com participantes: seed cancelado para preservar a rodada.'; end if; end $$;
insert into quiz_sessions (slug,titulo,periodo) values ('mack-dcs-a05-2026-2','Aula 05 — Quiz: o servidor de ingestão da Aula 04','2026-2') on conflict (slug) do update set titulo=excluded.titulo;
with novas as (
  insert into quiz_questions (session_slug,ordem,enunciado,alternativas,segundos,tema,secao,peso) values
  ('mack-dcs-a05-2026-2', 1, 'Um produtor manda para POST /ingest o envelope {"data_tag": "livros", "data": {...}, "timestamp": 1793401058101}, com o próprio horário. O corpo é JSON válido e tem menos de 1 MiB. O que a API responde, e por quê?', '["202, e o timestamp do produtor substitui o horário de recebimento na tabela.", "422, porque o envelope é fechado e o timestamp é sempre do servidor.", "400, porque um campo fora do contrato torna o corpo um JSON inválido.", "202, e o campo a mais é descartado antes de publicar na fila."]'::jsonb, 90, 'Envelope fechado', 'Aula 04, seção 5.1', 1),
  ('mack-dcs-a05-2026-2', 2, 'A API do servidor de ingestão responde 202 Accepted a um envelope válido. O que esse código garante ao produtor naquele momento?', '["Que a linha já está no ClickHouse e aparece no próximo SELECT do analista.", "Que o lote do envelope já foi gravado no raw e no bronze do RustFS.", "Que o payload passou pelo schema do domínio declarado em data_tag.", "Que a mensagem está na fila ingestao, com a publicação confirmada pelo broker."]'::jsonb, 90, 'O que o 202 promete', 'Aula 04, seções 5.1 e 6.1', 1),
  ('mack-dcs-a05-2026-2', 3, 'Um produtor AMQP publica direto na fila ingestao uma mensagem com data_tag "vendas", que não está em DOMINIOS. Ninguém recebe 422. O que o consumidor faz com ela?', '["Valida de novo, grava em raw/ingestao_rejeitados/ com o motivo e dá ack.", "Não dá ack, para o broker entregar de novo até o produtor corrigir a tag.", "Insere no ClickHouse, porque o envelope só é validado na API HTTP.", "Cria o domínio vendas, já que fonte nova é só uma etiqueta nova."]'::jsonb, 90, 'Rejeitado pela fila', 'Aula 04, seções 5.1 e 6 (RF-03)', 1),
  ('mack-dcs-a05-2026-2', 4, 'O consumidor grava raw, bronze, ClickHouse e manifesto e só então dá ack no lote. Um colega propõe dar ack assim que as mensagens chegam, para nunca gerar duplicata. O que a troca muda?', '["Nada no resultado, porque o RabbitMQ guarda em disco as mensagens com ack.", "A entrega vira exatamente uma vez, porque ack e gravação ficam no mesmo passo.", "A entrega vira no máximo uma vez: uma queda antes do flush perde o lote em memória.", "A entrega vira pelo menos uma vez, porque o broker reentrega o que recebeu ack."]'::jsonb, 90, 'Garantias de entrega', 'Aula 04, seções 6.2 e 8.1 (ADR-003)', 1),
  ('mack-dcs-a05-2026-2', 5, 'Com FLUSH_N=500 e FLUSH_SEGUNDOS=2, um produtor manda um envelope num momento sem outro tráfego, recebe 202 e, um segundo depois, não encontra a linha no ClickHouse. Como ler esse caso?', '["O servidor perdeu a mensagem, porque o 202 só sai depois do lote gravado.", "O lote não encheu e o flush espera o relógio; a linha aparece em cerca de 2,05 s.", "O ClickHouse ainda não fez o merge da parte nova, que só fica visível depois dele.", "O consumidor espera chegar 500 envelopes e só grava com o lote cheio."]'::jsonb, 90, 'Latência até consultável', 'Aula 04, seções 6.3 e 6.5', 1),
  ('mack-dcs-a05-2026-2', 6, 'O ClickHouse fica fora do ar por 20 minutos e recusa o INSERT de cada flush. O RustFS e o RabbitMQ continuam no ar. O que o servidor faz com cada lote nesse intervalo?', '["Grava o lote só no lake, dá ack e marca o manifesto como ok para recarregar depois.", "Descarta o lote e dá ack, porque o raw já guarda os envelopes como chegaram.", "Pula o ClickHouse e segue consumindo a fila, com o lote guardado em memória.", "Deixa raw e bronze gravados, grava manifesto erro_clickhouse, não dá ack e reconecta."]'::jsonb, 90, 'Ordem dos destinos e manifesto', 'Aula 04, seções 8.1 e 8.2 (ADR-002 e ADR-003)', 1),
  ('mack-dcs-a05-2026-2', 7, 'Na preparação, o flush completo (raw, bronze, ClickHouse e manifesto) de 1 linha custou 30,8 ms, e o de 500 linhas custou 31,6 ms. O que esses dois números mostram?', '["Cada gravação tem custo fixo; em lote de 500, o custo por linha cai quase 500 vezes.", "O RustFS fica mais rápido com arquivos grandes e passa a dominar o tempo do flush.", "O ClickHouse comprime melhor os lotes grandes e grava 500 linhas no mesmo tempo.", "A diferença é ruído de medição, e o tamanho do lote não muda a vazão do consumidor."]'::jsonb, 90, 'Custo fixo do micro-lote', 'Aula 04, seções 8.3 e 11.3', 1),
  ('mack-dcs-a05-2026-2', 8, 'No ClickHouse 26.8, async_insert e wait_for_async_insert vêm ligados por padrão. O consumidor da aula é um cliente só, que manda o lote inteiro num INSERT e espera a confirmação. O que acontece se ele usar o padrão?', '["Os INSERTs ficam mais rápidos, porque o buffer do servidor junta os lotes do consumidor.", "O ClickHouse passa a descartar os lotes repetidos que a fila reentrega depois da queda.", "Cada INSERT espera o buffer do servidor; o de uma linha passou de 4,0 ms para 55,9 ms.", "O INSERT volta sem esperar a gravação, e o ack pode sair antes de a linha existir."]'::jsonb, 90, 'async_insert com um cliente só', 'Aula 04, seções 11.2 e 14', 1),
  ('mack-dcs-a05-2026-2', 9, 'Na tabela de pouso, data_json é do tipo JSON. Com a configuração padrão, o coletado_em 2026-10-30T19:27:52-03:00 de um livro foi guardado como 2026-10-30 22:27:52. Qual é o problema e qual é a correção da aula?', '["O instante ficou errado em três horas; a correção é gravar timestamp em DateTime64(3).", "O ClickHouse recusou o caminho; a correção é declarar data_json como String.", "O campo virou texto; a correção é converter coletado_em com toDateTime na consulta.", "O -03:00 se perdeu na inferência; o INSERT desliga a inferência de datas e fica String."]'::jsonb, 90, 'Inferência de tipos no JSON', 'Aula 04, seções 7.4 e 13.3', 1),
  ('mack-dcs-a05-2026-2', 10, 'No teste de queda, o servidor foi morto entre o manifesto e o ack. Depois da drenagem, a tabela tinha 31.765 linhas para 31.265 publicadas, e o lake tinha 64 manifestos ok para 63 lotes. Como o grupo mostra que houve duplicata e nenhuma perda?', '["Pelo count() agrupado por timestamp: cada valor repetido é uma linha reentregue.", "Pelas distintas por (timestamp, data_json): 31.265, porque o timestamp sozinho não é único.", "Pelo número de manifestos: 64 menos 63 dá o lote perdido, que precisa ser reenviado.", "Pelas partes ativas do ClickHouse: uma parte a mais indica o lote gravado duas vezes."]'::jsonb, 90, 'Teste de queda e duplicatas', 'Aula 04, seções 7.2 e 12.2', 2)
  on conflict (session_slug,ordem) do update set enunciado=excluded.enunciado, alternativas=excluded.alternativas, segundos=excluded.segundos, tema=excluded.tema, secao=excluded.secao, peso=excluded.peso
  returning id,ordem
)
insert into quiz_answer_key (question_id,correta,explicacao)
select n.id,g.correta,g.explicacao from novas n join (values
  (1, 1, 'O envelope tem só data_tag e data, e um campo a mais é recusado com 422 e o motivo; é o exemplo invalido_422_campo_extra_timestamp.json. Aceitar o campo deixaria a dúvida sobre qual hora vale, a do produtor ou a da ingestão. O servidor acrescenta o timestamp em unix milissegundos na hora em que recebeu o envelope; a hora do evento, se o produtor quiser mandá-la, vai dentro de data, como o coletado_em dos livros. O 400 fica para o corpo que nem JSON é.'),
  (2, 3, 'A RFC 9110 define o 202 como requisição aceita para processamento que ainda não terminou. No servidor da aula, ele só sai depois da confirmação do broker, e por isso significa que a mensagem está na fila, em disco. A gravação no lake e no ClickHouse acontece depois, no flush do consumidor. Na medição, o 202 levou 1,51 ms de mediana e o 422, 0,53 ms: cerca de 1 ms é a publicação confirmada. O conteúdo de data não é validado nesta aula; o schema por domínio fica para a Aula 07.'),
  (3, 0, 'O RabbitMQ aceita qualquer sequência de bytes, e quem publica direto na fila não recebe resposta. Por isso o consumidor valida o envelope outra vez e, se ele for inválido, grava em raw/ingestao_rejeitados/data=D/ um arquivo com recebido_em_ms, o motivo e o corpo, e dá ack. Sem ack, o broker entregaria a mensagem para sempre e ela bloquearia o consumidor. Fonte nova exige a etiqueta em DOMINIOS no .env; sem esse registro, um erro de digitação viraria um domínio silencioso. A Aula 06 troca a pasta por uma dead letter exchange.'),
  (4, 2, 'Com ack depois de gravar, a entrega é pelo menos uma vez: se o processo morre antes do ack, a fila reentrega e nada se perde, mas o lote pode se repetir. Com ack ao receber, a mensagem sai da fila antes de chegar aos destinos, e um kill -9 com 500 envelopes em memória perde os 500. A ADR-003 escolheu a primeira, e o RNF-02 assume a consequência: perda zero e duplicatas contadas. Exatamente uma vez exigiria gravação e ack atômicos ou um destino que descarte a repetição, como o ReplacingMergeTree da Aula 06.'),
  (5, 1, 'Sem outro tráfego, o lote de 500 nunca enche e o flush acontece pelo relógio, 2 s depois do primeiro envelope. Na medição com o RustFS, a mediana foi 2.053 ms: 2.000 ms de espera e cerca de 50 ms de trabalho, o que bate com os 49 ms medidos com FLUSH_N=1. Durante a carga de telemetria, o lote enche antes, e a mediana caiu para 145 ms. Por isso o RNF de latência diz "até cerca de 2 s" e declara a condição de tráfego. A parte nova fica consultável logo após o INSERT; o merge acontece em segundo plano.'),
  (6, 3, 'A ordem do flush é raw, bronze, ClickHouse, manifesto e ack. Quando o INSERT falha, raw e bronze já estão gravados, o manifesto sai com status erro_clickhouse e o texto do erro, e a linha do ack não executa. As mensagens voltam num lote novo depois da reconexão, e a fila cresce enquanto o ClickHouse está fora; esse é o custo aceito na ADR-002. Manifesto ok quer dizer lote completo nas três camadas, e por isso arquivos sem manifesto ok ficam fora do reprocesso.'),
  (7, 0, 'Raw, bronze, INSERT e manifesto têm custo fixo de alguns milissegundos cada, quase independente do tamanho do lote. Por linha, o lote de 1 gasta 30,8 ms e o de 500, 31,6 / 500 = 0,063 ms. Um dia de telemetria (31.265 linhas) drenou em cerca de 6 s com lote de 500, contra 524,5 s linha a linha na primeira rodada. Com FLUSH_N=1, o ClickHouse criou 31.265 partes e fez cerca de 19.600 merges; as partes ativas no fim escondem esse custo.'),
  (8, 2, 'O async_insert é um micro-lote do lado do servidor, útil quando muitos clientes mandam poucas linhas. Com um cliente só, o buffer não tem com quem juntar, e cada INSERT espera pelo menos async_insert_busy_timeout_min_ms, 50 ms. A mediana do INSERT de uma linha foi 55,9 ms com o padrão e 4,0 ms com async_insert=0; numa carga de 2.000 mensagens com FLUSH_N=1, a drenagem levou 143,99 s contra 22,03 s. Como wait_for_async_insert=1 está ligado, o cliente espera a gravação. Por isso o .env.example traz CLICKHOUSE_ASYNC_INSERT=0: o consumidor já faz o lote.'),
  (9, 3, 'O tipo JSON infere o tipo de cada caminho no INSERT. Com o padrão, inferiu coletado_em como DateTime e converteu para UTC: o instante está certo, mas a informação de que a coleta foi às 19h27 em Brasília se perdeu. O consumidor insere com input_format_try_infer_dates = 0 e input_format_try_infer_datetimes = 0, e o caminho fica String, igual ao que chegou, conferido com JSONAllPathsWithTypes. A silver converte o texto para TIMESTAMPTZ de forma explícita. Quem insere por outro caminho, como o reprocesso a partir do bronze, precisa passar as mesmas configurações.'),
  (10, 1, 'O lote inteiro voltou e foi gravado de novo em raw, bronze e ClickHouse: 31.765 − 31.265 = 500 linhas, exatamente um lote, com dois manifestos ok para o mesmo conteúdo. As linhas distintas por (timestamp, data_json), com toJSONString(data_json), continuaram em 31.265, e isso separa duplicata de perda. O timestamp sozinho não serve: é a hora em que a API recebeu o envelope, e todos os objetos de um envelope com lista, como os 40 boletins PTAX, têm o mesmo valor. Partes ativas não contam linhas, e o manifesto a mais mostra a repetição do lote.')
) as g(ordem,correta,explicacao) on g.ordem=n.ordem
on conflict (question_id) do update set correta=excluded.correta, explicacao=excluded.explicacao;
insert into quiz_host_tokens (session_slug,token) values ('mack-dcs-a05-2026-2','__QUIZ_HOST_TOKEN__') on conflict (session_slug) do update set token=excluded.token;
do $$ begin if (select count(*) from quiz_questions where session_slug='mack-dcs-a05-2026-2') <> 10 then raise exception 'A sala deve conter exatamente 10 perguntas'; end if; end $$;
commit;
